function store() {
  // "strong" consistency so a save is immediately visible to the next read,
  // important since multiple reps may be reading/writing within seconds of
  // each other.
  return getStore({ name: STORE_NAME, consistency: 'strong' });
}

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    },
  });
}

async function readAll(s) {
  const [groupPrices, customerDeals, wholesalerDeals, tempDeals, customerFlags, customerGlassPricing, customerPickFees, customerOffPremisePricing, customerCartonDeliveryFees, rsmTargets, rsmTargetProtected, activations, trucks, orders, deliveryRuns, manualOutletsRaw, customerDeliveryDetails, naDistributions, rsmZoneOverrides, naTargets, customGroups, groupMemberOverrides, fyForecastInputs, naSkuTargets, naSkuQuarterOverrides, hlDismissals, postcodeZoneOverrides, customerRsmOverrides, groupLastUpdated] = await Promise.all([
    s.get('groupPrices', { type: 'json' }),
    s.get('customerDeals', { type: 'json' }),
    s.get('wholesalerDeals', { type: 'json' }),
    s.get('tempDeals', { type: 'json' }),
    s.get('customerFlags', { type: 'json' }),
    s.get('customerGlassPricing', { type: 'json' }),
    s.get('customerPickFees', { type: 'json' }),
    s.get('customerOffPremisePricing', { type: 'json' }),
    s.get('customerCartonDeliveryFees', { type: 'json' }),
    s.get('rsmTargets', { type: 'json' }),
    s.get('rsmTargetProtected', { type: 'json' }),
    s.get('activations', { type: 'json' }),
    s.get('trucks', { type: 'json' }),
    s.get('orders', { type: 'json' }),
    s.get('deliveryRuns', { type: 'json' }),
    s.get('manualOutlets', { type: 'json' }),
    s.get('customerDeliveryDetails', { type: 'json' }),
    s.get('naDistributions', { type: 'json' }),
    s.get('rsmZoneOverrides', { type: 'json' }),
    s.get('naTargets', { type: 'json' }),
    s.get('customGroups', { type: 'json' }),
    s.get('groupMemberOverrides', { type: 'json' }),
    s.get('fyForecastInputs', { type: 'json' }),
    s.get('naSkuTargets', { type: 'json' }),
    s.get('naSkuQuarterOverrides', { type: 'json' }),
    s.get('hlDismissals', { type: 'json' }),
    s.get('postcodeZoneOverrides', { type: 'json' }),
    s.get('customerRsmOverrides', { type: 'json' }),
    s.get('groupLastUpdated', { type: 'json' }),
  ]);
  // vipContacts is seeded exactly once — the first time anyone loads the app after this feature
  // ships, the blob won't exist yet (null, not just empty), so we seed it from VIP_CONTACTS_SEED
  // and save it immediately. Every load after that reads the real, saved blob — additions/edits/
  // deletes from the VIP Contacts tab are never overwritten by a future deploy of this function.
  let vipContacts = await s.get('vipContacts', { type: 'json' });
  if (vipContacts === null) {
    const seededAt = new Date().toISOString();
    vipContacts = VIP_CONTACTS_SEED.map((c, i) => ({
      id: 'vip_seed_' + i, ...c, updatedBy: "Feb'26 customer list import", updatedAt: seededAt,
    }));
    await s.setJSON('vipContacts', vipContacts);
  }
  // One-time batch seed (Round 48): merge the LMG Bottlemart QLD/Northern NSW import into
  // manualOutlets — same "seed once" idea as vipContacts above, but flag-gated (lmgSeedApplied)
  // rather than null-gated, since manualOutlets is very likely already non-empty from real usage
  // by the time this ships — a null/empty check would never fire. Flag-gating also means a store
  // someone deliberately deletes afterward stays deleted, instead of silently reappearing on the
  // next load. Runs here (inside the same readAll() every GET already calls) rather than as a
  // separate POST action, so it applies automatically the moment this deploy goes live — no extra
  // client-side trigger needed.
  let manualOutlets = manualOutletsRaw || {};
  const lmgSeedApplied = await s.get('lmgSeedApplied', { type: 'json' });
  if (!lmgSeedApplied || !lmgSeedApplied.applied) {
    let added = false;
    LMG_SEED_OUTLETS.forEach((rec) => {
      if (!manualOutlets[rec.id]) { manualOutlets[rec.id] = rec; added = true; }
    });
    if (added) await s.setJSON('manualOutlets', manualOutlets);
    await s.setJSON('lmgSeedApplied', { applied: true, appliedAt: new Date().toISOString(), count: LMG_SEED_OUTLETS.length });
  }
  // One-time batch seed (Round 49): same pattern as the LMG block above, for the Star Liquor Group
  // (Star Liquor / Bob's Bulk Booze / Sense of Taste) QLD/Northern NSW import.
  const slgSeedApplied = await s.get('slgSeedApplied', { type: 'json' });
  if (!slgSeedApplied || !slgSeedApplied.applied) {
    let addedSlg = false;
    SLG_SEED_OUTLETS.forEach((rec) => {
      if (!manualOutlets[rec.id]) { manualOutlets[rec.id] = rec; addedSlg = true; }
    });
    if (addedSlg) await s.setJSON('manualOutlets', manualOutlets);
    await s.setJSON('slgSeedApplied', { applied: true, appliedAt: new Date().toISOString(), count: SLG_SEED_OUTLETS.length });
  }
  // Round 79: same one-time batch seed, for the Liquor Legends outlet-export import (LL + VLG
  // banner codes, zone-allocated non-interstate postcodes only).
  const llgSeedApplied = await s.get('llgSeedApplied', { type: 'json' });
  if (!llgSeedApplied || !llgSeedApplied.applied) {
    let addedLlg = false;
    LLG_SEED_OUTLETS.forEach((rec) => {
      if (!manualOutlets[rec.id]) { manualOutlets[rec.id] = rec; addedLlg = true; }
    });
    if (addedLlg) await s.setJSON('manualOutlets', manualOutlets);
    await s.setJSON('llgSeedApplied', { applied: true, appliedAt: new Date().toISOString(), count: LLG_SEED_OUTLETS.length });
  }
  // One-time batch migration (Round 50): 155 of the 271 LMG/SLG seed stores above have since been
  // confidently matched to their real ontap/OTD outlet id (via licence number for LMG, or exact
  // suburb+postcode+name match for SLG, looked up through the OTD Outlet Search tool). Renaming a
  // manualOutlets record's own id (both the dict key and its internal .id field) to that real id is
  // what lets it auto-supersede once real sales data starts flowing under that id — see
  // realOutletIds.has(c.id) client-side. This does NOT touch manualOutlets values at all, only the
  // key/id — name, banner, email, custType etc. all carry over unchanged. Flag-gated exactly like
  // the seeds above so a rename only ever happens once, and a record the user deletes or edits
  // afterward (under its new id) is never reverted or reapplied.
  const otdReassignApplied = await s.get('otdReassignAppliedV1', { type: 'json' });
  if (!otdReassignApplied || !otdReassignApplied.applied) {
    let renamedCount = 0;
    OTD_OUTLET_ID_REASSIGNMENTS.forEach((r) => {
      const rec = manualOutlets[r.oldId];
      if (rec && !manualOutlets[r.newId]) {
        delete manualOutlets[r.oldId];
        manualOutlets[r.newId] = { ...rec, id: r.newId };
        renamedCount++;
      }
    });
    if (renamedCount > 0) await s.setJSON('manualOutlets', manualOutlets);
    await s.setJSON('otdReassignAppliedV1', { applied: true, appliedAt: new Date().toISOString(), count: renamedCount });
  }
  // One-time safety-net backfill (Round 51): the original SLG seed records (Round 49) never had a
  // majorGroup field set, so even after the Export Emails "universe" fix (Round 51 — see
  // eeUniverseOutlets() client-side) they still wouldn't show up under a "Star Liquor" banner-group
  // filter, since every real Star Liquor outlet is tagged majorGroup:'Star Liquor'. The
  // SLG_SEED_OUTLETS array above now carries majorGroup from the start, so this only ever needs to
  // patch records that seeded before this fix shipped (harmless/no-op otherwise).
  const slgMajorGroupBackfillApplied = await s.get('slgMajorGroupBackfillAppliedV1', { type: 'json' });
  if (!slgMajorGroupBackfillApplied || !slgMajorGroupBackfillApplied.applied) {
    const slgBanners = ['Star Liquor', "Bob's Bulk Booze", 'Sense Of Taste'];
    let patchedCount = 0;
    Object.values(manualOutlets).forEach((rec) => {
      if (slgBanners.includes(rec.banner) && !rec.majorGroup) { rec.majorGroup = 'Star Liquor'; patchedCount++; }
    });
    if (patchedCount > 0) await s.setJSON('manualOutlets', manualOutlets);
    await s.setJSON('slgMajorGroupBackfillAppliedV1', { applied: true, appliedAt: new Date().toISOString(), count: patchedCount });
  }
  return {
    groupPrices: groupPrices || {},
    customerDeals: customerDeals || {},
    wholesalerDeals: wholesalerDeals || {},
    tempDeals: tempDeals || [],
    customerFlags: customerFlags || {},
    customerGlassPricing: customerGlassPricing || {},
    customerPickFees: customerPickFees || {},
    customerOffPremisePricing: customerOffPremisePricing || {},
    customerCartonDeliveryFees: customerCartonDeliveryFees || {},
    rsmTargets: rsmTargets || {},
    rsmTargetProtected: rsmTargetProtected || {},
    activations: activations || [],
    trucks: trucks || [],
    orders: orders || [],
    deliveryRuns: deliveryRuns || [],
    manualOutlets: manualOutlets || {},
    customerDeliveryDetails: customerDeliveryDetails || {},
    naDistributions: naDistributions || {},
    vipContacts,
    rsmZoneOverrides: rsmZoneOverrides || {},
    naTargets: naTargets || {},
    customGroups: customGroups || [],
    groupMemberOverrides: groupMemberOverrides || {},
    fyForecastInputs: fyForecastInputs || {},
    naSkuTargets: naSkuTargets || {},
    naSkuQuarterOverrides: naSkuQuarterOverrides || {},
    hlDismissals: hlDismissals || {},
    postcodeZoneOverrides: postcodeZoneOverrides || {},
    customerRsmOverrides: customerRsmOverrides || {},
    groupLastUpdated: groupLastUpdated || {},
  };
}

export default async (req) => {
  if (req.method === 'OPTIONS') {
    return json({ ok: true });
  }

  const s = store();

  if (req.method === 'GET') {
    return json(await readAll(s));
  }

  if (req.method !== 'POST') {
    return json({ error: 'Method not allowed' }, 405);
  }

  let body;
  try {
    body = await req.json();
  } catch (err) {
    return json({ error: 'Invalid JSON body' }, 400);
  }

  const { action, payload } = body || {};
  if (!action) return json({ error: 'Missing action' }, 400);
  const now = new Date().toISOString();

  try {
    if (action === 'saveGroupPrice') {
      const { groupId, listPrice, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, listPrice, updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'setGroupEnabled') {
      const { groupId, enabled, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, enabled: !!enabled, updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'saveCustomerDeal') {
      const { outletId, groupId, dealX, updatedBy } = payload;
      const current = (await s.get('customerDeals', { type: 'json' })) || {};
      const key = outletId + '|' + groupId;
      if (Number(dealX) === 0) {
        delete current[key];
      } else {
        current[key] = { dealX: Number(dealX), updatedBy, updatedAt: now };
      }
      await s.setJSON('customerDeals', current);
      return json({ ok: true, customerDeals: current });
    }

    if (action === 'bulkApplyDeal') {
      const { outletId, groupIds, dealX, updatedBy } = payload;
      const current = (await s.get('customerDeals', { type: 'json' })) || {};
      (groupIds || []).forEach((groupId) => {
        const key = outletId + '|' + groupId;
        if (Number(dealX) === 0) delete current[key];
        else current[key] = { dealX: Number(dealX), updatedBy, updatedAt: now };
      });
      await s.setJSON('customerDeals', current);
      return json({ ok: true, customerDeals: current });
    }

    if (action === 'saveWholesalerDeal') {
      // A second, separate deal record for stock loaded into a wholesaler (ALM/ILG/PAR) rather
      // than bought direct — kept in its own blob key so it never collides/merges with customerDeals.
      const { outletId, groupId, dealX, wholesaler, updatedBy } = payload;
      const current = (await s.get('wholesalerDeals', { type: 'json' })) || {};
      const key = outletId + '|' + groupId;
      if (Number(dealX) === 0) {
        delete current[key];
      } else {
        current[key] = { dealX: Number(dealX), wholesaler: wholesaler || null, updatedBy, updatedAt: now };
      }
      await s.setJSON('wholesalerDeals', current);
      return json({ ok: true, wholesalerDeals: current });
    }

    if (action === 'bulkApplyWholesalerDeal') {
      const { outletId, groupIds, dealX, wholesaler, updatedBy } = payload;
      const current = (await s.get('wholesalerDeals', { type: 'json' })) || {};
      (groupIds || []).forEach((groupId) => {
        const key = outletId + '|' + groupId;
        if (Number(dealX) === 0) delete current[key];
        else current[key] = { dealX: Number(dealX), wholesaler: wholesaler || null, updatedBy, updatedAt: now };
      });
      await s.setJSON('wholesalerDeals', current);
      return json({ ok: true, wholesalerDeals: current });
    }

    if (action === 'saveNaDistribution') {
      // Manually-entered, quarterly store-distribution counts for Coles/Woolworths (Coles &
      // Woolworths tab) — we don't get real per-store listing data for these bulk/national
      // accounts the way we do for Sales Team accounts, so this is entered by hand and used to
      // compute units-per-store-per-week against real carton sales volume.
      const { quarterKey, ownerGroup, groupId, count, updatedBy } = payload;
      const current = (await s.get('naDistributions', { type: 'json' })) || {};
      const key = quarterKey + '|' + ownerGroup + '|' + groupId;
      const num = Math.max(0, Math.round(Number(count) || 0));
      if (num === 0) {
        delete current[key];
      } else {
        current[key] = { count: num, updatedBy, updatedAt: now };
      }
      await s.setJSON('naDistributions', current);
      return json({ ok: true, naDistributions: current });
    }

    if (action === 'saveTempDeal') {
      const { id, outletId, groupId, dealX, start, end, notes, updatedBy } = payload;
      const current = (await s.get('tempDeals', { type: 'json' })) || [];
      const newId = id || ('td_' + Date.now() + '_' + Math.round(Math.random() * 10000));
      const idx = current.findIndex((t) => t.id === newId);
      const rec = { id: newId, outletId, groupId, dealX: Number(dealX), start, end, notes: notes || '', updatedBy, updatedAt: now };
      if (idx >= 0) current[idx] = rec; else current.push(rec);
      await s.setJSON('tempDeals', current);
      return json({ ok: true, id: newId, tempDeals: current });
    }

    if (action === 'deleteTempDeal') {
      const { id } = payload;
      const current = (await s.get('tempDeals', { type: 'json' })) || [];
      const next = current.filter((t) => t.id !== id);
      await s.setJSON('tempDeals', next);
      return json({ ok: true, tempDeals: next });
    }

    if (action === 'saveCustomerFlag') {
      // field is 'pricingUpdated', 'metWithCustomer' (booleans), or 'notes' (string)
      const { outletId, field, value, updatedBy } = payload;
      const current = (await s.get('customerFlags', { type: 'json' })) || {};
      const existing = current[outletId] || { pricingUpdated: false, metWithCustomer: false };
      current[outletId] = { ...existing, [field]: value, updatedBy, updatedAt: now };
      await s.setJSON('customerFlags', current);
      return json({ ok: true, customerFlags: current });
    }

    if (action === 'saveGlassSize') {
      // Glass sizes are shared across every beer for a customer.
      const { outletId, glassKey, sizeMl, updatedBy } = payload;
      const current = (await s.get('customerGlassPricing', { type: 'json' })) || {};
      const existingOutlet = current[outletId] || {};
      const sizes = { ...(existingOutlet.sizes || {}), [glassKey]: Number(sizeMl) };
      current[outletId] = { ...existingOutlet, sizes, updatedBy, updatedAt: now };
      await s.setJSON('customerGlassPricing', current);
      return json({ ok: true, customerGlassPricing: current });
    }

    if (action === 'saveGlassPrice') {
      // Glass retail prices (inc GST) are set per SKU (groupId).
      const { outletId, groupId, glassKey, price, updatedBy } = payload;
      const current = (await s.get('customerGlassPricing', { type: 'json' })) || {};
      const existingOutlet = current[outletId] || {};
      const prices = { ...(existingOutlet.prices || {}) };
      prices[groupId] = { ...(prices[groupId] || {}), [glassKey]: Number(price) };
      current[outletId] = { ...existingOutlet, prices, updatedBy, updatedAt: now };
      await s.setJSON('customerGlassPricing', current);
      return json({ ok: true, customerGlassPricing: current });
    }

    if (action === 'savePickFee') {
      // Optional, shared between the Venues and Off Premise calculators. unitType is 'keg' or
      // 'carton'; fee may be null to clear it back to "not set" (blank).
      const { outletId, unitType, fee, updatedBy } = payload;
      const current = (await s.get('customerPickFees', { type: 'json' })) || {};
      const existing = current[outletId] || {};
      current[outletId] = { ...existing, [unitType]: (fee === null || fee === undefined) ? null : Number(fee), updatedBy, updatedAt: now };
      await s.setJSON('customerPickFees', current);
      return json({ ok: true, customerPickFees: current });
    }

    if (action === 'saveCartonDeliveryFee') {
      // Optional, used only by the Off Premise calculator's Wholesaler vs Direct comparison.
      // scenario is 'wholesaler' or 'direct'; fee may be null to clear it back to "not set" (blank).
      const { outletId, scenario, fee, updatedBy } = payload;
      const current = (await s.get('customerCartonDeliveryFees', { type: 'json' })) || {};
      const existing = current[outletId] || {};
      current[outletId] = { ...existing, [scenario]: (fee === null || fee === undefined) ? null : Number(fee), updatedBy, updatedAt: now };
      await s.setJSON('customerCartonDeliveryFees', current);
      return json({ ok: true, customerCartonDeliveryFees: current });
    }

    if (action === 'saveCartonPackQty') {
      // Cans per carton — set per SKU group on the Product List Prices page, since each SKU
      // can genuinely come in a different carton size. Used by both margin calculators.
      const { groupId, cartonPackQty, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, cartonPackQty: Number(cartonPackQty), updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'saveMultipackQty') {
      // Cans per multipack — set per SKU group (not per customer), since different beers can
      // come in different multipack sizes (e.g. a 4-pack vs a 6-pack).
      const { groupId, multipackQty, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, multipackQty: Number(multipackQty), updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'saveCanSizeMl') {
      // mL per can — set per SKU group, for display/reference alongside carton math.
      const { groupId, canSizeMl, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, canSizeMl: Number(canSizeMl), updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'saveOffPremisePrice') {
      // Carton/multipack/single retail prices (inc GST) are set per SKU (groupId). The
      // 'single' price is also shown on the Venues calculator for the same customer/SKU.
      const { outletId, groupId, priceType, price, updatedBy } = payload;
      const current = (await s.get('customerOffPremisePricing', { type: 'json' })) || {};
      const existingOutlet = current[outletId] || {};
      const prices = { ...(existingOutlet.prices || {}) };
      prices[groupId] = { ...(prices[groupId] || {}), [priceType]: Number(price) };
      current[outletId] = { ...existingOutlet, prices, updatedBy, updatedAt: now };
      await s.setJSON('customerOffPremisePricing', current);
      return json({ ok: true, customerOffPremisePricing: current });
    }

    if (action === 'saveRsmTarget') {
      // field is one of: totalVolumeTarget, kegVolumeTarget, cartonVolumeTarget,
      // kegListingsTarget, cartonListingsTarget. value may be null to clear it (back to blank).
      const { rsm, quarterKey, field, value, updatedBy } = payload;
      const current = (await s.get('rsmTargets', { type: 'json' })) || {};
      const key = rsm + '|' + quarterKey;
      const existing = current[key] || {};
      if (value === null || value === undefined) {
        const updated = { ...existing };
        delete updated[field];
        current[key] = { ...updated, updatedBy, updatedAt: now };
      } else {
        current[key] = { ...existing, [field]: Number(value), updatedBy, updatedAt: now };
      }
      await s.setJSON('rsmTargets', current);
      return json({ ok: true, rsmTargets: current });
    }

    if (action === 'saveRsmTargetsBulk') {
      // Bulk sibling of saveRsmTarget above, for operations that touch many fields at once (the FY
      // Listing Growth Forecast's "Apply Q1-Q4" / "Apply Q1-Q4 for all RSMs" buttons — up to 16
      // fields for one RSM, or dozens across every RSM). Firing one saveRsmTarget request PER FIELD
      // for a bulk apply used to race against itself: each request did its own independent
      // read-current-blob -> merge one field -> write-whole-blob-back round trip, so several
      // in-flight requests could all read the same "before" snapshot and the last one to finish
      // writing would silently discard whatever the others had just added — losing some of the
      // applied targets a few seconds later once the client's periodic refresh pulled the
      // (incomplete) server state back down. Doing the whole batch as ONE read + ONE write removes
      // the race entirely, since there's nothing left to interleave with.
      const { entries, updatedBy } = payload;
      const current = (await s.get('rsmTargets', { type: 'json' })) || {};
      (entries || []).forEach(({ rsm, quarterKey, field, value }) => {
        const key = rsm + '|' + quarterKey;
        const existing = current[key] || {};
        if (value === null || value === undefined) {
          const updated = { ...existing };
          delete updated[field];
          current[key] = { ...updated, updatedBy, updatedAt: now };
        } else {
          current[key] = { ...existing, [field]: Number(value), updatedBy, updatedAt: now };
        }
      });
      await s.setJSON('rsmTargets', current);
      return json({ ok: true, rsmTargets: current });
    }

    if (action === 'saveHlDismissal') {
      // Closed / Using Sub Distributor — global across all 5 Hit Lists (keyed by outlet id or the
      // synthetic "fg:gi:si" prospect key), NOT quarter-scoped. A durable fact about the customer
      // that persists until someone explicitly undoes it via clearHlDismissal below.
      const { key, entry } = payload;
      const current = (await s.get('hlDismissals', { type: 'json' })) || {};
      current[key] = entry;
      await s.setJSON('hlDismissals', current);
      return json({ ok: true, hlDismissals: current });
    }

    if (action === 'clearHlDismissal') {
      const { key } = payload;
      const current = (await s.get('hlDismissals', { type: 'json' })) || {};
      delete current[key];
      await s.setJSON('hlDismissals', current);
      return json({ ok: true, hlDismissals: current });
    }

    if (action === 'saveRsmTargetProtected') {
      // Marks (or clears) a quarter's targets as manually set via the standalone per-quarter
      // Volume Target Calculator — see fyForecastApply() client-side, which skips writing any
      // quarter marked protected here rather than silently overwriting a manager's deliberate
      // figures with the FY Listing Growth Forecast's bulk cascade.
      const { rsm, quarterKey, protectedFlag, updatedBy } = payload;
      const current = (await s.get('rsmTargetProtected', { type: 'json' })) || {};
      const key = rsm + '|' + quarterKey;
      if (protectedFlag) current[key] = true; else delete current[key];
      await s.setJSON('rsmTargetProtected', current);
      return json({ ok: true, rsmTargetProtected: current });
    }

    if (action === 'saveActivation') {
      const { id, outletId, productType, activationType, start, end, dealX, bonusStock, pos, consumerPricing, groupId, tempDealId, updatedBy, photos } = payload;
      const current = (await s.get('activations', { type: 'json' })) || [];
      const newId = id || ('act_' + Date.now() + '_' + Math.round(Math.random() * 10000));
      const idx = current.findIndex((a) => a.id === newId);
      const rec = {
        id: newId, outletId, productType, activationType, start, end,
        dealX: Number(dealX) || 0, bonusStock: bonusStock || '', pos: pos || '', consumerPricing: consumerPricing || '',
        groupId: groupId || null, tempDealId: tempDealId || null,
        // Photo evidence carried through from the client (see acEditingPhotos in netlify_part4.js,
        // which stashes photos across the delete-then-recreate edit flow so they never get wiped).
        photos: Array.isArray(photos) ? photos : [],
        updatedBy, updatedAt: now,
      };
      if (idx >= 0) current[idx] = rec; else current.push(rec);
      await s.setJSON('activations', current);
      return json({ ok: true, id: newId, activations: current });
    }

    if (action === 'deleteActivation') {
      const { id } = payload;
      const current = (await s.get('activations', { type: 'json' })) || [];
      const next = current.filter((a) => a.id !== id);
      await s.setJSON('activations', next);
      return json({ ok: true, activations: next });
    }

    if (action === 'addActivationPhoto') {
      // Adds one photo to an already-saved activation in place — used by the Activations list's
      // inline "+ photo" control, which shouldn't have to go through the full edit-form
      // delete-then-recreate flow just to attach a photo.
      const { id, photo } = payload;
      const current = (await s.get('activations', { type: 'json' })) || [];
      const idx = current.findIndex((a) => a.id === id);
      if (idx >= 0) {
        if (!Array.isArray(current[idx].photos)) current[idx].photos = [];
        current[idx].photos.push(photo);
        await s.setJSON('activations', current);
      }
      return json({ ok: true, activations: current });
    }

    if (action === 'removeActivationPhoto') {
      const { id, photoIdx } = payload;
      const current = (await s.get('activations', { type: 'json' })) || [];
      const idx = current.findIndex((a) => a.id === id);
      if (idx >= 0 && Array.isArray(current[idx].photos)) {
        current[idx].photos.splice(photoIdx, 1);
        await s.setJSON('activations', current);
      }
      return json({ ok: true, activations: current });
    }

    if (action === 'saveWeightKg') {
      // Weight per sale unit (per keg, or per carton) — used by the Orders/Delivery tools to
      // work out a load's total weight and check it against a truck's capacity.
      const { groupId, weightKg, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, weightKg: Number(weightKg), updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'saveTargetMarginMultipack') {
      // Round 64: per-SKU target margin % (multipack pack type) — used by the Off Premise Quick
      // Margin Calculator to back-solve a suggested shelf price for each deal tier. null clears it
      // back to "not set" rather than storing a real (if useless) 0%.
      const { groupId, targetMarginMultipack, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, targetMarginMultipack: targetMarginMultipack == null ? null : Number(targetMarginMultipack), updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'saveTargetMarginCarton') {
      // Round 64: per-SKU target margin % (carton pack type) — see saveTargetMarginMultipack above.
      const { groupId, targetMarginCarton, updatedBy } = payload;
      const current = (await s.get('groupPrices', { type: 'json' })) || {};
      const existing = current[groupId] || {};
      current[groupId] = { ...existing, targetMarginCarton: targetMarginCarton == null ? null : Number(targetMarginCarton), updatedBy, updatedAt: now };
      await s.setJSON('groupPrices', current);
      return json({ ok: true, groupPrices: current });
    }

    if (action === 'addCustomGroup') {
      // Adds a brand-new, self-serve SKU group (either a fresh custom product or a group
      // split off from an existing multi-member group). Upserted by id so re-saving an
      // edited custom group (e.g. re-running a split) just replaces the prior record.
      const { group } = payload;
      const current = (await s.get('customGroups', { type: 'json' })) || [];
      const idx = current.findIndex((g) => g.id === group.id);
      if (idx >= 0) current[idx] = group; else current.push(group);
      await s.setJSON('customGroups', current);
      return json({ ok: true, customGroups: current });
    }

    if (action === 'splitGroupMembers') {
      // Splits one or more member SKUs off an existing group into a brand-new group.
      // remainingMembers trims the ORIGINAL group's member list (stored as an override,
      // since the original group itself is baked reference data, not editable in place);
      // newGroup is the freshly created group holding the split-off members.
      const { originalGroupId, remainingMembers, newGroup } = payload;
      const currentGroups = (await s.get('customGroups', { type: 'json' })) || [];
      const idx = currentGroups.findIndex((g) => g.id === newGroup.id);
      if (idx >= 0) currentGroups[idx] = newGroup; else currentGroups.push(newGroup);
      await s.setJSON('customGroups', currentGroups);
      const currentOverrides = (await s.get('groupMemberOverrides', { type: 'json' })) || {};
      currentOverrides[originalGroupId] = remainingMembers;
      await s.setJSON('groupMemberOverrides', currentOverrides);
      return json({ ok: true, customGroups: currentGroups, groupMemberOverrides: currentOverrides });
    }

    if (action === 'saveTruck') {
      const { id, name, maxWeightKg, updatedBy } = payload;
      const current = (await s.get('trucks', { type: 'json' })) || [];
      const newId = id || ('truck_' + Date.now() + '_' + Math.round(Math.random() * 10000));
      const idx = current.findIndex((t) => t.id === newId);
      const rec = { id: newId, name, maxWeightKg: Number(maxWeightKg), updatedBy, updatedAt: now };
      if (idx >= 0) current[idx] = rec; else current.push(rec);
      await s.setJSON('trucks', current);
      return json({ ok: true, id: newId, trucks: current });
    }

    if (action === 'deleteTruck') {
      const { id } = payload;
      const current = (await s.get('trucks', { type: 'json' })) || [];
      const next = current.filter((t) => t.id !== id);
      await s.setJSON('trucks', next);
      return json({ ok: true, trucks: next });
    }

    if (action === 'saveOrder') {
      // The whole order record (lines[], delivery{}, etc.) is sent as one object — simpler and
      // less error-prone than flattening a deeply nested shape into individual args. The server
      // just assigns an id if it's new and upserts by id, same pattern as everywhere else.
      const { order } = payload;
      const current = (await s.get('orders', { type: 'json' })) || [];
      const newId = order.id || ('ord_' + Date.now() + '_' + Math.round(Math.random() * 10000));
      const idx = current.findIndex((o) => o.id === newId);
      const rec = { ...order, id: newId, updatedAt: now };
      if (idx >= 0) current[idx] = rec; else current.push(rec);
      await s.setJSON('orders', current);
      return json({ ok: true, id: newId, orders: current });
    }

    if (action === 'deleteOrder') {
      const { id } = payload;
      const current = (await s.get('orders', { type: 'json' })) || [];
      const next = current.filter((o) => o.id !== id);
      await s.setJSON('orders', next);
      return json({ ok: true, orders: next });
    }

    if (action === 'saveRun') {
      // Same whole-object upsert pattern as saveOrder.
      const { run } = payload;
      const current = (await s.get('deliveryRuns', { type: 'json' })) || [];
      const newId = run.id || ('run_' + Date.now() + '_' + Math.round(Math.random() * 10000));
      const idx = current.findIndex((r) => r.id === newId);
      const rec = { ...run, id: newId, updatedAt: now };
      if (idx >= 0) current[idx] = rec; else current.push(rec);
      await s.setJSON('deliveryRuns', current);
      return json({ ok: true, id: newId, deliveryRuns: current });
    }

    if (action === 'deleteRun') {
      const { id } = payload;
      const current = (await s.get('deliveryRuns', { type: 'json' })) || [];
      const next = current.filter((r) => r.id !== id);
      await s.setJSON('deliveryRuns', next);
      return json({ ok: true, deliveryRuns: next });
    }

    if (action === 'saveManualOutlet') {
      // Customers added before they have any sales history — keyed by outlet ID (either a real
      // ID the rep already knows, e.g. from a licensing/POS system, or an auto-generated
      // placeholder from the client if not). Dictionary-keyed like groupPrices/customerFlags,
      // since the id IS the key — no separate "assign a new id" step needed like orders/runs.
      const { outlet } = payload;
      const current = (await s.get('manualOutlets', { type: 'json' })) || {};
      current[outlet.id] = { ...outlet, updatedAt: now };
      await s.setJSON('manualOutlets', current);
      return json({ ok: true, id: outlet.id, manualOutlets: current });
    }

    if (action === 'deleteManualOutlet') {
      const { id } = payload;
      const current = (await s.get('manualOutlets', { type: 'json' })) || {};
      delete current[id];
      await s.setJSON('manualOutlets', current);
      return json({ ok: true, manualOutlets: current });
    }

    if (action === 'assignRealOutletId') {
      // Renames a manualOutlets record's key (and its internal .id) from oldId to newId — the same
      // mechanical rename the OTD batch reassignment performs in readAll() above, just single-record
      // and human-triggered from the Outlet ID Review tool (New Customers page). The client has
      // already confirmed newId isn't already a REAL (sales-history) outlet — only the client has
      // CRM_DATA to know that — so this only re-checks what the server CAN see: another manualOutlets
      // record already sitting at newId.
      const { oldId, newId } = payload;
      const current = (await s.get('manualOutlets', { type: 'json' })) || {};
      if (!current[oldId]) return json({ error: 'That customer record no longer exists — refresh and try again.' }, 400);
      if (current[newId]) return json({ error: `${newId} already belongs to an existing customer (${current[newId].name}) — use "Merge into existing" instead.` }, 400);
      const rec = { ...current[oldId], id: newId };
      delete current[oldId];
      current[newId] = rec;
      await s.setJSON('manualOutlets', current);
      return json({ ok: true, manualOutlets: current });
    }

    if (action === 'mergeOutletRecords') {
      // Folds oldId's data into newId (an existing real or manual outlet already in the system),
      // filling gaps on the target without ever overwriting something it already has, across every
      // outlet-keyed collection — then deletes oldId's manualOutlets entry. Mirrors app3.js's
      // mergeOutletRecords() exactly; see that function's comment for the full rationale.
      // targetIsReal is decided client-side (only the client has CRM_DATA to know whether newId has
      // real sales history) and trusted here — this server has no way to check it independently.
      const { oldId, newId, targetIsReal, updatedBy } = payload;
      if (oldId === newId) return json({ error: "Can't merge a customer into itself." }, 400);

      const manualOutletsCur = (await s.get('manualOutlets', { type: 'json' })) || {};
      const source = manualOutletsCur[oldId];
      if (!source) return json({ error: 'That customer record no longer exists — refresh and try again.' }, 400);

      const dd = (await s.get('customerDeliveryDetails', { type: 'json' })) || {};
      if (targetIsReal) {
        const rec = { ...(dd[newId] || {}) };
        let ddChanged = false;
        if (!rec.email && source.email) { rec.email = source.email; ddChanged = true; }
        if (!rec.contactPhone && source.phone) { rec.contactPhone = source.phone; ddChanged = true; }
        if (!rec.familyGroup && source.familyGroup) { rec.familyGroup = source.familyGroup; ddChanged = true; }
        if (ddChanged) { rec.updatedBy = updatedBy; rec.updatedAt = now; dd[newId] = rec; }
      } else {
        const targetRec = { ...(manualOutletsCur[newId] || { id: newId, name: source.name }) };
        let profileChanged = !manualOutletsCur[newId];
        ['address', 'suburb', 'state', 'postcode', 'phone', 'email', 'rsm', 'custType', 'zone', 'familyGroup'].forEach((k) => {
          if (!targetRec[k] && source[k]) { targetRec[k] = source[k]; profileChanged = true; }
        });
        if (profileChanged) {
          targetRec.updatedBy = updatedBy; targetRec.updatedAt = now;
          if (!manualOutletsCur[newId]) { targetRec.createdBy = source.createdBy; targetRec.createdAt = source.createdAt; }
          manualOutletsCur[newId] = targetRec;
        }
        // customerDeliveryDetails gets a plain gap-fill copy too, when the target is itself another
        // manual/prospect record (the real-target branch above already folded the relevant fields in).
        if (dd[oldId] !== undefined && dd[newId] === undefined) dd[newId] = dd[oldId];
      }
      delete dd[oldId];
      await s.setJSON('customerDeliveryDetails', dd);

      const simpleBlobKeys = ['customerFlags', 'customerGlassPricing', 'customerPickFees', 'customerOffPremisePricing', 'customerCartonDeliveryFees', 'hlDismissals'];
      const simpleResults = {};
      for (const blobKey of simpleBlobKeys) {
        const cur = (await s.get(blobKey, { type: 'json' })) || {};
        if (cur[oldId] !== undefined) {
          if (cur[newId] === undefined) cur[newId] = cur[oldId];
          delete cur[oldId];
          await s.setJSON(blobKey, cur);
        }
        simpleResults[blobKey] = cur;
      }

      const compositeResults = {};
      for (const blobKey of ['customerDeals', 'wholesalerDeals']) {
        const cur = (await s.get(blobKey, { type: 'json' })) || {};
        let ccChanged = false;
        Object.keys(cur).forEach((key) => {
          const sep = key.indexOf('|');
          if (sep === -1 || key.slice(0, sep) !== oldId) return;
          const newKey = newId + key.slice(sep);
          if (cur[newKey] === undefined) cur[newKey] = cur[key];
          delete cur[key];
          ccChanged = true;
        });
        if (ccChanged) await s.setJSON(blobKey, cur);
        compositeResults[blobKey] = cur;
      }

      const arrayResults = {};
      for (const blobKey of ['tempDeals', 'activations', 'orders']) {
        const cur = (await s.get(blobKey, { type: 'json' })) || [];
        let acChanged = false;
        cur.forEach((rec) => { if (rec.outletId === oldId) { rec.outletId = newId; acChanged = true; } });
        if (acChanged) await s.setJSON(blobKey, cur);
        arrayResults[blobKey] = cur;
      }

      delete manualOutletsCur[oldId];
      await s.setJSON('manualOutlets', manualOutletsCur);

      return json({
        ok: true, targetIsReal,
        manualOutlets: manualOutletsCur,
        customerDeliveryDetails: dd,
        customerFlags: simpleResults.customerFlags,
        customerGlassPricing: simpleResults.customerGlassPricing,
        customerPickFees: simpleResults.customerPickFees,
        customerOffPremisePricing: simpleResults.customerOffPremisePricing,
        customerCartonDeliveryFees: simpleResults.customerCartonDeliveryFees,
        hlDismissals: simpleResults.hlDismissals,
        customerDeals: compositeResults.customerDeals,
        wholesalerDeals: compositeResults.wholesalerDeals,
        tempDeals: arrayResults.tempDeals,
        activations: arrayResults.activations,
        orders: arrayResults.orders,
      });
    }

    if (action === 'saveDeliveryDetails') {
      // Access notes/on-site contact/preferred timing per customer — dictionary-keyed by outlet
      // ID like customerFlags/manualOutlets. Saved as one whole record per "Save" click (not
      // per-field), matching the batch-save UX on the Customer Summary page. Merges onto any
      // existing record (rather than replacing it outright) so this never clobbers email/email2/
      // familyGroup saved separately via 'saveContactInfo' below — same record, two save buttons.
      const { outletId, accessNotes, contactName, contactPhone, preferredDay, preferredWindow, updatedBy } = payload;
      const current = (await s.get('customerDeliveryDetails', { type: 'json' })) || {};
      const rec = { ...(current[outletId] || {}), accessNotes, contactName, contactPhone, preferredDay, preferredWindow, updatedBy, updatedAt: now };
      const isBlank = !rec.accessNotes && !rec.contactName && !rec.contactPhone && !rec.preferredWindow
        && (!rec.preferredDay || rec.preferredDay === 'Any day') && !rec.email && !rec.email2 && !rec.familyGroup;
      if (isBlank) delete current[outletId]; else current[outletId] = rec;
      await s.setJSON('customerDeliveryDetails', current);
      return json({ ok: true, customerDeliveryDetails: current });
    }

    if (action === 'saveContactInfo') {
      // Email(s) + family/franchise group per customer — shares the same customerDeliveryDetails
      // record as 'saveDeliveryDetails' above (one record per outlet), merging in rather than
      // replacing so the two "Save" buttons on Customer Summary never stomp on each other.
      const { outletId, email, email2, familyGroup, updatedBy } = payload;
      const current = (await s.get('customerDeliveryDetails', { type: 'json' })) || {};
      const rec = { ...(current[outletId] || {}), email, email2, familyGroup, updatedBy, updatedAt: now };
      const isBlank = !rec.accessNotes && !rec.contactName && !rec.contactPhone && !rec.preferredWindow
        && (!rec.preferredDay || rec.preferredDay === 'Any day') && !rec.email && !rec.email2 && !rec.familyGroup;
      if (isBlank) delete current[outletId]; else current[outletId] = rec;
      await s.setJSON('customerDeliveryDetails', current);
      return json({ ok: true, customerDeliveryDetails: current });
    }

    if (action === 'saveVipContact') {
      // Industry contacts who aren't purchasing outlets themselves — a plain array with a
      // client-generated id, upserted by id (same shape/pattern as 'saveActivation' above).
      const { contact } = payload;
      const current = (await s.get('vipContacts', { type: 'json' })) || [];
      const idx = current.findIndex((c) => c.id === contact.id);
      const rec = { ...contact, updatedAt: now };
      if (idx >= 0) current[idx] = rec; else current.push(rec);
      await s.setJSON('vipContacts', current);
      return json({ ok: true, vipContacts: current });
    }

    if (action === 'deleteVipContact') {
      const { id } = payload;
      const current = (await s.get('vipContacts', { type: 'json' })) || [];
      const next = current.filter((c) => c.id !== id);
      await s.setJSON('vipContacts', next);
      return json({ ok: true, vipContacts: next });
    }

    if (action === 'saveRsmZoneOverride') {
      // Lets the user immediately reassign which RSM a zone belongs to, ahead of the periodic
      // Ontap-driven data pipeline refresh — { [zone]: rsmName }, keyed by zone. Saving an empty/
      // blank rsm value clears the override for that zone (reverting it to whatever Ontap has on
      // file, once the app applies this against the baked outlet data — see applyRsmZoneOverrides()
      // in netlify_part1.js).
      const { zone, rsm } = payload;
      const current = (await s.get('rsmZoneOverrides', { type: 'json' })) || {};
      const clean = (rsm || '').trim();
      if (clean) current[zone] = clean; else delete current[zone];
      await s.setJSON('rsmZoneOverrides', current);
      return json({ ok: true, rsmZoneOverrides: current });
    }

    if (action === 'savePostcodeZoneOverride') {
      // Round 56: lets the user reassign an individual postcode to a different zone than the
      // imported postcode database (POSTCODE_ZONE_SEED, baked into CRM_DATA) says — { [postcode]:
      // zoneName }, keyed by postcode. Saving an empty/blank zone value clears the override for
      // that postcode, reverting it to whatever the postcode database (or, failing that, Ontap)
      // has on file — see applyRsmZoneOverrides() in netlify_part1.js.
      const { postcode, zone } = payload;
      const current = (await s.get('postcodeZoneOverrides', { type: 'json' })) || {};
      const clean = (zone || '').trim();
      if (clean) current[postcode] = clean; else delete current[postcode];
      await s.setJSON('postcodeZoneOverrides', current);
      return json({ ok: true, postcodeZoneOverrides: current });
    }

    if (action === 'saveCustomerRsmOverride') {
      // Round 56: pins ONE specific customer to an RSM regardless of what their postcode/zone
      // would otherwise resolve to — { [outletId]: rsmName }. Highest-priority layer in the RSM
      // resolution order — see applyRsmZoneOverrides() in netlify_part1.js. Saving an empty/blank
      // rsm value clears the pin for that customer.
      const { outletId, rsm } = payload;
      const current = (await s.get('customerRsmOverrides', { type: 'json' })) || {};
      const clean = (rsm || '').trim();
      if (clean) current[outletId] = clean; else delete current[outletId];
      await s.setJSON('customerRsmOverrides', current);
      return json({ ok: true, customerRsmOverrides: current });
    }

    if (action === 'updateGroupLastUpdated') {
      // Round 57: tracks when a periodically-refreshed batch list (Family Groups, VIP Contacts,
      // LMG, Star Liquor — see GROUP_TRACKER_DEFS in netlify_part1.js) was last brought up to
      // date. Purely informational — never feeds any resolution logic elsewhere. Saving an
      // empty/blank date clears the record back to "Not yet set".
      const { key, date, updatedBy } = payload;
      const current = (await s.get('groupLastUpdated', { type: 'json' })) || {};
      const clean = (date || '').trim();
      if (clean) current[key] = { date: clean, updatedBy: updatedBy || 'Unknown', updatedAt: new Date().toISOString() };
      else delete current[key];
      await s.setJSON('groupLastUpdated', current);
      return json({ ok: true, groupLastUpdated: current });
    }

    if (action === 'saveNaTarget') {
      // National Accounts (Coles & Woolworths) volume target, per FY quarter — sits outside the
      // RSM-based rsmTargets collection, used by the Total Volume page to build a combined
      // company-wide target line. value may be null to clear it (back to blank).
      const { quarterKey, cartonVolumeTarget, updatedBy } = payload;
      const current = (await s.get('naTargets', { type: 'json' })) || {};
      const existing = current[quarterKey] || {};
      if (cartonVolumeTarget === null || cartonVolumeTarget === undefined) {
        const updated = { ...existing };
        delete updated.cartonVolumeTarget;
        current[quarterKey] = { ...updated, updatedBy, updatedAt: now };
      } else {
        current[quarterKey] = { ...existing, cartonVolumeTarget: Number(cartonVolumeTarget), updatedBy, updatedAt: now };
      }
      await s.setJSON('naTargets', current);
      return json({ ok: true, naTargets: current });
    }

    if (action === 'saveFyForecastInput') {
      // FY Listing Growth Forecast (Set Targets page) — one manually-entered new-listings-per-
      // quarter growth number per RSM per field (kegs/cartons kept separate), keyed 'rsm|fy'.
      // Q1's baseline is real start-of-quarter listings; Q2-Q4 cascade from the previous quarter's
      // own forecasted ending listings (computed client-side in fyForecastCompute) — this collection
      // only stores the manual growth inputs, not the derived quarterly figures.
      const { rsm, fy, field, value, updatedBy } = payload;
      const key = rsm + '|' + fy;
      const current = (await s.get('fyForecastInputs', { type: 'json' })) || {};
      const existing = current[key] || {};
      if (value === null || value === undefined) {
        const updated = { ...existing };
        delete updated[field];
        current[key] = { ...updated, updatedBy, updatedAt: now };
      } else {
        current[key] = { ...existing, [field]: Number(value), updatedBy, updatedAt: now };
      }
      await s.setJSON('fyForecastInputs', current);
      return json({ ok: true, fyForecastInputs: current });
    }

    if (action === 'saveNaSkuTarget') {
      // National Accounts per-SKU annual volume target, keyed 'groupId|fy' — the annual figure the
      // user enters is split across the 4 FY quarters client-side using each SKU's own last-FY
      // seasonality (mirrors how monthly targets are seasonally weighted elsewhere in the app).
      const { groupId, fy, value, updatedBy } = payload;
      const key = groupId + '|' + fy;
      const current = (await s.get('naSkuTargets', { type: 'json' })) || {};
      if (value === null || value === undefined) {
        const next = { ...current };
        delete next[key];
        await s.setJSON('naSkuTargets', next);
        return json({ ok: true, naSkuTargets: next });
      }
      current[key] = { annualVolumeTarget: Number(value), updatedBy, updatedAt: now };
      await s.setJSON('naSkuTargets', current);
      return json({ ok: true, naSkuTargets: current });
    }

    if (action === 'saveNaSkuQuarterOverride') {
      // Manual override for ONE quarter of a National Accounts SKU's volume target, keyed
      // 'groupId|fy|q' — replaces the auto seasonal-split value for that quarter only, letting a
      // manager type in a known non-seasonal figure (a promo, a one-off bulk order, a delisting)
      // without touching the SKU's annual target or its other quarters.
      const { groupId, fy, q, value, updatedBy } = payload;
      const key = groupId + '|' + fy + '|' + q;
      const current = (await s.get('naSkuQuarterOverrides', { type: 'json' })) || {};
      if (value === null || value === undefined) {
        const next = { ...current };
        delete next[key];
        await s.setJSON('naSkuQuarterOverrides', next);
        return json({ ok: true, naSkuQuarterOverrides: next });
      }
      current[key] = { value: Number(value), updatedBy, updatedAt: now };
      await s.setJSON('naSkuQuarterOverrides', current);
      return json({ ok: true, naSkuQuarterOverrides: current });
    }

    return json({ error: 'Unknown action: ' + action }, 400);
  } catch (err) {
    return json({ error: String((err && err.message) || err) }, 500);
  }
};
